 case EmailLocalExpr:return validateExpr(v.Input)
 case RegexpReplaceExpr:return validateExpr(v.Input)};return nil
}

type Matcher interface{Match(string)bool}
type MatcherFn func(string)bool
func(f MatcherFn)Match(s string)bool{return f(s)}
func NewAnyMatcher(in []string)(Matcher,error){ms:=make([]Matcher,0,len(in));for _,s:=range in{m,err:=NewMatcher(s);if err!=nil{return nil,err};ms=append(ms,m)};return MatcherFn(func(s string)bool{for _,m:=range ms{if m.Match(s){return true}};return false}),nil}
type MatchExpression struct { prefix,suffix string; expr Expr }
func (m *MatchExpression)Match(in string)bool{
 if !strings.HasPrefix(in,m.prefix)||!strings.HasSuffix(in,m.suffix)||len(in)<len(m.prefix)+len(m.suffix){return false}
 middle:=in[len(m.prefix):len(in)-len(m.suffix)]
 v,err:=m.expr.Evaluate(EvaluateContext{MatcherInput:middle});if err!=nil{return false};return v.(bool)
}
func NewMatcher(value string)(Matcher,error){
 prefix,body,suffix,has,err:=template(value);if err!=nil{return nil,err}
 var e Expr
 if has {e,err=parse(body)}else{pat:=body;if !strings.HasPrefix(body,"''^")||!strings.HasSuffix(body,"$"){pat="''^"+utils.GlobToRegexp(body)+"$"};var re *regexp.Regexp;re,err=compile(pat);if err==nil{e=RegexpMatchExpr{pat,re}}}
 if err!=nil{return nil,trace.BadParameter("invalid matcher %q: %v",value,err)}
 if e.Kind()!=reflect.Bool{return nil,trace.BadParameter("matcher %q must evaluate to a boolean",value)}
 return &MatchExpression{prefix:prefix,suffix:suffix,expr:e},nil
}
