package parse

import (
	"reflect"
	"regexp"
	"strings"

	"github.com/gravitational/teleport/lib/utils"
	"github.com/gravitational/trace"
	"github.com/vulcand/predicate"
)

const LiteralNamespace = "literal"
const maxExpressionDepth = 100

// Expression combines a string AST with optional template text.
type Expression struct {
	prefix, suffix string
	expr           Expr
}

func (p *Expression) Namespace() string {
	if v, ok := p.expr.(VarExpr); ok {
		return v.Namespace
	}
	if _, ok := p.expr.(StringLitExpr); ok {
		return LiteralNamespace
	}
	return ""
}
func (p *Expression) Name() string {
	if v, ok := p.expr.(VarExpr); ok {
		return v.Name
	}
	return ""
}
func (p *Expression) Interpolate(traits map[string][]string, validations ...func(string, string) error) ([]string, error) {
	ctx := EvaluateContext{VarValue: func(v VarExpr) ([]string, error) {
		if len(validations) > 0 && validations[0] != nil {
			if err := validations[0](v.Namespace, v.Name); err != nil {
				return nil, err
			}
		}
		if v.Namespace == LiteralNamespace {
			return []string{v.Name}, nil
		}
		values, ok := traits[v.Name]
		if !ok {
			return nil, trace.NotFound("variable %s is not found", v.String())
		}
		return values, nil
	}}
	value, err := p.expr.Evaluate(ctx)
	if err != nil {
		return nil, trace.Wrap(err)
	}
	values := value.([]string)
	out := make([]string, 0, len(values))
	for _, v := range values {
		if v != "" {
			out = append(out, p.prefix+v+p.suffix)
		}
	}
	if len(out) == 0 {
		return nil, trace.NotFound("variable interpolation result is empty")
	}
	return out, nil
}

var reVariable = regexp.MustCompile(`^([^{}]*){{([^{}]*)}}([^{}]*)$`)

func template(value string) (prefix, body, suffix string, has bool, err error) {
	value = strings.TrimSpace(value)
	m := reVariable.FindStringSubmatch(value)
	if m == nil {
		if strings.Contains(value, "{{") || strings.Contains(value, "}}") || strings.ContainsAny(value, "{}") {
			return "", "", "", false, trace.BadParameter("malformed template usage %q: expected {{expression}}", value)
		}
		return "", value, "", false, nil
	}
	return m[1], strings.TrimSpace(m[2]), m[3], true, nil
}
func NewExpression(value string) (*Expression, error) {
	prefix, body, suffix, has, err := template(value)
	if err != nil {
		return nil, err
	}
	if !has {
		return &Expression{expr: StringLitExpr{body}}, nil
	}
	e, err := parse(body)
	if err != nil {
		return nil, trace.BadParameter("invalid expression %q: %v", value, err)
	}
	if e.Kind() != reflect.String {
		return nil, trace.BadParameter("expression %q must evaluate to a string", value)
	}
	return &Expression{prefix: prefix, suffix: suffix, expr: e}, nil
}

func buildVarExpr(fields []string) (interface{}, error) {
	if len(fields) == 1 {
		if fields[0] == "internal" || fields[0] == "external" || fields[0] == LiteralNamespace {
			return VarExpr{Namespace: fields[0]}, nil
		}
	}
	if len(fields) != 2 {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	switch fields[0] {
	case "internal", "external", LiteralNamespace:
	default:
		return nil, trace.BadParameter("unsupported variable namespace %q", fields[0])
	}
	if fields[1] == "" {
		return nil, trace.BadParameter("variable name is empty")
	}
	return VarExpr{Namespace: fields[0], Name: fields[1]}, nil
}
func buildVarExprFromProperty(base, key interface{}) (interface{}, error) {
	v, ok := base.(VarExpr)
	if !ok || v.Name != "" {
		return nil, trace.BadParameter("variable must have exactly two parts: namespace.name")
	}
	name, ok := key.(string)
	if !ok || name == "" {
		return nil, trace.BadParameter("variable index must be a nonempty quoted name")
	}
	v.Name = name
	return v, nil

)

func TestExpression(t *testing.T) {
	tests := []struct {
		in     string
		traits map[string][]string
		want   []string
	}{
		{" foo ", nil, []string{"foo"}},
		{" {{ internal.foo }} ", map[string][]string{"foo": {"a", "b"}}, []string{"a", "b"}},
		{`{{internal["foo"]}}`, map[string][]string{"foo": {"bar"}}, []string{"bar"}},
		{`x-{{regexp.replace(email.local(external.mail), "@.*", "")}}-y`, map[string][]string{"mail": {"a@example.com"}}, nil},
		{`{{regexp.replace(email.local(external.mail), "^a$", "b")}}`, map[string][]string{"mail": {"a@example.com"}}, []string{"b"}},
		{`{{regexp.replace("bar-baz", "bar-(.*)", "$1")}}`, nil, []string{"baz"}},
		{`{{email.local("Alice <alice@example.com>")}}`, nil, []string{"alice"}},
		{`{{regexp.replace(" a ", "a", "b")}}`, nil, []string{" b "}},
	}
	for _, tt := range tests {
		t.Run(tt.in, func(t *testing.T) {
			e, err := NewExpression(tt.in)
			require.NoError(t, err)
			got, err := e.Interpolate(tt.traits)
			if tt.want == nil {
				require.True(t, trace.IsNotFound(err))
				return
			}
			require.NoError(t, err)
			require.Equal(t, tt.want, got)
		})
	}
}
func TestInvalidExpression(t *testing.T) {
	for _, s := range []string{`{{internal}}`, `{{internal.foo.bar}}`, `{{internal.foo["bar"]}}`, `{{other.foo}}`, `{{"foo"}}`, `{{123}}`, `{{regexp.match("foo")}}`, `{{regexp.replace(internal.foo, external.bar, "x")}}`, `{{regexp.replace(internal.foo, "(", "x")}}`, `{{regexp.replace(regexp.match("x"), "x", "y")}}`, `{{email.local(internal.foo, "x")}}`, `{{email.local(regexp.match("x"))}}`, `{{internal.foo`, `internal.foo}}`} {
		t.Run(s, func(t *testing.T) { _, err := NewExpression(s); require.True(t, trace.IsBadParameter(err), "%v", err) })
	}
}
func TestInterpolationValidation(t *testing.T) {
	e, err := NewExpression(`{{regexp.replace(internal.foo, "a", "b")}}`)
	require.NoError(t, err)
	_, err = e.Interpolate(map[string][]string{"foo": {"a"}}, func(ns, name string) error { return trace.BadParameter("unsupported variable %q", name) })
	require.True(t, trace.IsBadParameter(err))
	_, err = e.Interpolate(nil)
	require.True(t, trace.IsNotFound(err))
	require.Contains(t, err.Error(), "internal.foo")
}
func TestMatcher(t *testing.T) {
	for _, tt := range []struct {
		expr, input string
		want        bool
	}{{"foo", "foo", true}, {"foo*", "foobar", true}, {"foo*", "xfoobar", false}, {`^foo.*$`, "foobar", true}, {`x{{regexp.match("bar")}}y`, "xbary", true}, {`x{{regexp.not_match("bar")}}y`, "xbary", false}} {
		m, err := NewMatcher(tt.expr)
		require.NoError(t, err)
		require.Equal(t, tt.want, m.Match(tt.input))
	}
	for _, s := range []string{`{{external.foo}}`, `{{regexp.match(external.foo)}}`, `{{email.local("a@b.com")}}`, `{{regexp.match("(")}}`} {
		_, err := NewMatcher(s)
		require.True(t, trace.IsBadParameter(err), "%v", err)
	}
